import sys

def main():
    import math
    n, a = map(int, sys.stdin.read().split())
    min_diff = float('inf')
    best_v1, best_v2, best_v3 = 0, 0, 0
    for v2 in range(1, n + 1):
        for v1 in range(1, n + 1):
            if v1 == v2:
                continue
            for v3 in range(1, n + 1):
                if v3 == v2 or v3 == v1:
                    continue
                angle = abs((v1 - v2) % n + (v3 - v2) % n - a)
                if angle < min_diff:
                    min_diff = angle
                    best_v1, best_v2, best_v3 = v1, v2, v3
    print(best_v1, best_v2, best_v3)

